    color: rgb(var(--layout-text-color));
}
body.hidden {
    overflow: clip !important;
    touch-action: none !important;
    -ms-touch-action: none !important;
    overscroll-behavior-y: none;
    display: block;
}
.body.disable-selection {
    user-select: none !important;
    -webkit-user-select: none !important;
}

.md-no-anim, .md-no-anim * {
    transition: none !important;
}

/* #region Fade in */

.fade-in.inside-content {
    position: relative;
}

.fade-in::before {
    content: "";
    position: absolute;
    inset: 0; 
    display: var(--fade-in-element-display, block);
    background-color: rgb(var(--layout-background-color));
    opacity: 1;
    transition: opacity var(--fade-in-duration) ease-out;
    pointer-events: none; 
    z-index: 9999; 
}

.fade-in.inside-content::before {
    top: var(--header-group-height, 0);
}

.body.loaded .fade-in::before,
.body.loaded.fade-in::before {
    opacity: 0;
}

@media screen and (min-width: 921px) {
    .html-fade-in:has(.overlapping-section--first) .fade-in::before {
        all: unset;
    }
    .html-fade-in:has(.overlapping-section--first) .inside-content::before {
        content: "";
        position: absolute;
        inset: 0; 
        top: 0px;
        display: var(--fade-in-element-display, block);
        background-color: rgb(var(--layout-background-color));
        opacity: 1;
        transition: opacity var(--fade-in-duration) ease-out;
        pointer-events: none; 
        z-index: 9999; 
    }
    .html-fade-in:has(.overlapping-section--first) .loaded .inside-content::before {
        opacity: 0;
    }
}

