.swiper .swiper-button {
    background-color: rgb(var(--base-button-color));
    border-radius: var(--other-buttons-radius);
    padding: 5px;
    --swiper-navigation-size: fit-content;
    box-shadow: 0px 1px 0px rgba(0, 0, 0, 0.05);
    transform: translateY(-50%);
}

