    --swiper-pagination-bullet-height: 2px;

    width: 100%;
    bottom: 0;
    inset-inline-start: 0;
    height: 2px;
    display: flex;
    background-color: rgba(var(--layout-text-color),.15);
}

@media (hover: hover) {
    .card:hover .swiper-button-prev:not(.swiper-button-hidden) {
        opacity: 1;
