}
.color-custom .rte:not(.popup-content) blockquote::after,
.color-invert .rte:not(.popup-content) blockquote::after  {
    background-color: rgb(var(--layout-text-color));
}
.rte::-webkit-scrollbar { 
    width: 0;
    height: 0;
    display: none;
}
.rte::-moz-scrollbar { 
    width: 0;
    height: 0;
    display: none;
    scrollbar-width: none;
}
.rte iframe {
    max-width: 100%;
