/* Component search modal */
.search-modal {
    width: 100vw;
    height: 40vh;
    min-height: 460px;
    position: fixed;
    z-index: 1000;
    left: 0;
    background-color: rgb(var(--popup-background-color));
    color: rgb(var(--layout-text-color));
    transition: height .3s var(--transition-timing-function); 
    -webkit-overflow-scrolling: touch;
}

.search-modal.open {
    top: 0;
    opacity: 1;
    animation: modalOpen .3s var(--transition-timing-function);
}

.search-modal.searching {
    height: 90dvh;
}

.search-modal .component-tabs {
    overflow-x: clip;
}

.search-modal.searching .component-tabs {
    overflow-x: auto;
}

body.hidden .search-modal .scroll-area {
    height: 100%;
}

@keyframes modalOpen {
    0% {
        top: -40px;
        opacity: 0;
    }
    100% {
        top: 0;
        opacity: 1;
    }
}

.search-modal__container {
    max-width: 1440px;
    margin: 0 auto;
}

.predictive-search-container {
    display: block;
}

.search-modal .button-wrapper {
    padding-inline-end: 16px;
    background-color: rgb(var(--popup-background-color)); 
    padding-top: 16px;
    top: 0;
}

.search-modal .search-field__wrapper {
    position: sticky;
    position: -webkit-sticky;
    top: 60px;
    width: 100%;
    z-index: 5;
    padding-bottom: 32px;
    background-color: rgb(var(--popup-background-color));
}

.search-modal__content .field.search-field {
    max-width: 960px;
    margin: 0 auto;
    padding-bottom: 12px;
}
.search-modal__content .field.search-field .search-field__icon {
    height: 24px;
    width: 24px;
}

.search-modal__form {
    display: flex;
    flex-direction: column;
    position: relative;
}

.search-modal.searching .search__menu {
    display: none;
}

.search__menu {
    max-width: 960px;
    width: 100%;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 6px;
    opacity: 0;
}

.search-modal.open .search__menu {
    animation: menuOpacity .6s var(--transition-timing-function);
    opacity: 1;
}

@keyframes menuOpacity {
    0% {
        opacity: 0;
    }
    50% {
        opacity: 0;
    }
    100% {
        opacity: 1;
    }
}

.search__menu-title {
    color: rgba(var(--layout-text-color), .7);
}

.search__menu .menu__item {
    display: flex;
    align-items: center;
    transition: opacity var(--animation-duration) var(--transition-timing-function);
}

.search__button {
    color: rgb(var(--layout-text-color));
    word-break: keep-all;
    position: relative;
}

.search-modal.searching .search__button {
    opacity: 1;
}

.search__button-text.hidden,
.predictive-search-results {
    opacity: 0;
}
.search__button-text {
    opacity: 1;
    transition: opacity .3s var(--transition-timing-function);
}

.predictive-search__loading-state,
.predictive-search--header,
.predictive-search-results {
    position: relative;
 }

.predictive-search-results-tabs {
    display: flex;
    flex-wrap: nowrap;
    width: fit-content;
    max-width: 100%;
    margin: 0 auto;
    padding-bottom: 32px;
    overflow-x: auto;
    z-index: 5;
    background-color: rgb(var(--layout-background-color));
    -ms-overflow-style: none;
    scrollbar-width: none;
}

.search-modal::-webkit-scrollbar { 
    width: 0;
    height: 0;
    display: none;
}

.search-modal::-moz-scrollbar { 
    width: 0;
    height: 0;
    display: none;
    scrollbar-width: none;
}

.search-modal.searching .predictive-search-results {
    opacity: 1;
    animation: tabsMoving .6s var(--transition-timing-function);
}

@keyframes tabsMoving {
    0% {
        top: 20px;
        opacity: 0;
    }
    100% {
        top: 0;
        opacity: 1;
    }
}

.predictive-search-results-tabs {
    background-color: rgb(var(--popup-background-color));
}
.predictive-search-results-content {
    overflow: clip;
    position: relative;
    background-color: rgb(var(--popup-background-color));
}

.predictive-search-results-content .tab-content-js {
    position: absolute;
    top: 0;
    padding-bottom: 64px;
    padding-top: 32px;
