    position: absolute;
    top: 0;
    bottom: 0;
    display: block;
    border-radius: 4px;
    cursor: grab;
    background-color: rgb(var(--layout-text-color));
    width: 250px;
  }

  .slider-scrollbar__thumb.dragging {
    cursor: grabbing;
    top: -2px;
    height: 8px;
  }

.slider-scrollbar__thumb::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    display: block;
    height: 30px;
    top: -14px;
}

.slider-buttons-items.slider-scrollbar {
