}
.media-with-tabs__tab {
    display: inline;
    cursor: pointer;
    opacity: 0.7;
    width: fit-content;
}
.media-with-tabs__tab.active {
    opacity: 1;
    cursor: default;
}
.media-with-tabs__tabs {
    display: block;
}
.media-with-tabs__tabs:not(:first-child) {
