}

.section-bg-gradient.mega-menu-drawer .first-nested__list,
.section-bg-gradient.mega-menu-drawer .second-nested__list {
    background: transparent;
}

.mega-menu-drawer .top-level-item[open] + .nested-submenu .first-nested__list {
    pointer-events: all;
    visibility: visible;
}

.mega-menu-drawer .main-drawer-menu .menu .menu__item-title {
    padding: 8px 0;
