/* #region Stagger animation */

.stagger.stagger--basic {
    --stagger-step: 0.03s;
    --stagger-offset-y: 10px;
    --stagger-bottom-y: -10px;
}

.stagger.stagger--sophisticated {
    --stagger-step: 0.05s;
    --stagger-offset-y: 20px;
    --stagger-bottom-y: -20px;
}

.mega-menu-drawer.open .nested-submenu.nested-submenu--stagger-in,
.filter-form.open,
.search-modal.open {
    --stagger-initial-delay: 200ms;
}

.menu-drawer .stagger__item {
    opacity: 0;
}

.drawer.active .stagger__item,
.default-menu-drawer.open .stagger__item:not(.localization-container):not(.store-selector-container),
.mega-menu-drawer.open .stagger__item:not(.pinned-block):not(.localization-container):not(.store-selector-container),
.mega-menu-drawer.open .nested-submenu.nested-submenu--stagger-in .stagger__item,
.filter-form.open .stagger__item:not(.facets-footer),
.menu__item-title.open ~ .menu__dropdown-container.mega-menu .stagger__item,
.menu__dropdown-grandchild-container--hover.active .stagger__item,
.menu__item-title--header.open + .menu__dropdown-container .stagger__item,
.search-modal.open .search-modal__menu-item.stagger__item,
.disclosure__list-wrapper:not([hidden="true"]) .disclosure__item.stagger__item {
  opacity: 0;
  transform: translateY(var(--stagger-offset-y));
  animation: drawerStaggerIn var(--animation-duration) var(--transition-timing-function) both;
  animation-delay: calc(var(--stagger-initial-delay, 10ms) + var(--stagger-step) * var(--item-index));
}

.mega-menu-drawer.open .stagger__item.localization-container,
.mega-menu-drawer.open .stagger__item.store-selector-container,
.mega-menu-drawer.menu-drawer--left.open .stagger__item.localization-container,
.mega-menu-drawer.menu-drawer--left.open .stagger__item.store-selector-container,
.default-menu-drawer.open .stagger__item.localization-container,
.default-menu-drawer.open .stagger__item.store-selector-container  {
  position: relative;
  opacity: 0;
  transform: none;
  top: var(--stagger-offset-y);
  animation: drawerStaggerInTop var(--animation-duration) var(--transition-timing-function) both;
  animation-delay: calc(var(--stagger-initial-delay, 10ms) + var(--stagger-step) * var(--item-index));
}

.mega-menu-drawer.open .pinned-block.stagger__item,
.mega-menu-drawer.menu-drawer--left.open .pinned-block.stagger__item,
.filter-form.open .stagger__item.facets-footer {
  position: fixed;
  top: auto;
  bottom: var(--stagger-bottom-y);
  animation: drawerStaggerInBottom var(--animation-duration) var(--transition-timing-function) both;
  animation-delay: calc(var(--stagger-initial-delay, 10ms) + var(--stagger-step) * var(--item-index));
}

.mega-menu-drawer.open .nested-submenu .stagger__item {
  opacity: 1;
  transform: none;
  animation: none;
}

@keyframes drawerStaggerIn {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes drawerStaggerInTop {
  from {
    opacity: 0;
    top: var(--stagger-offset-y);
  }
  to {
    opacity: 1;
    top: 0;
  }
}

@keyframes drawerStaggerInBottom {
  from {
    opacity: 0;
    bottom: var(--stagger-bottom-y);
  }
  to {
    opacity: 1;
    bottom: 0;
  }
}

/* #endregion */

/* Menu drawer */
.default-menu-drawer {
    background-color: #fff;
    position: fixed;
    width: 100vw;
    height: 100dvh;
    z-index: 25;
    top: 0;
    display: block !important;
    background-color: rgb(var(--layout-background-color));
    contain: layout paint;
}

.default-menu-drawer .scroll-area {
    padding: 56px 0 64px;
}

.default-menu-drawer[hidden] {
    opacity: 0;
    pointer-events: none;
    visibility: hidden;
}

.default-menu-drawer:not([hidden]) {
    opacity: 1;
    visibility: visible;
    pointer-events: all;
    animation: openMenuDrawer var(--animation-duration) var(--transition-timing-function);
}

@keyframes openMenuDrawer {
    0% {
        opacity: 0;
    }
    100% {
        opacity: 1;
    }
}

.default-menu-drawer__content {
    display: grid;
    max-width: 1440px;
    margin: 0 auto;
    grid-template-columns: repeat(var(--grid-columns), calc((100% - var(--grid-gap) * (var(--grid-columns) - 1)) / var(--grid-columns)));
    position: relative;
    z-index: 10;
}
.menu-drawer .default-menu-drawer__content .section-navigation-block {
    position: relative;
    border: 1px dashed transparent;
}

.default-menu-drawer__content--spacious {
    padding: 128px var(--left-and-right-paddings);
    gap: 128px 120px;
    --grid-gap: 120px;
}

.default-menu-drawer__content--compact {
    padding: 48px var(--left-and-right-paddings);
    gap: 48px 120px;
    --grid-gap: 120px;
}

.default-menu-drawer .menu-drawer__close {
    position: fixed;
    top: 24px;
    inset-inline-end: 24px;
    cursor: pointer;
}

.default-menu-drawer .menu-drawer__close svg {
    display: block;
    width: auto;
}

.line-container--menu-drawer {
    display: flex;
    justify-content: var(--line-alignment);
}

.line {
    width: 100%;
    height: var(--line-width);
    background-color: rgba(var(--layout-text-color), var(--line-opacity));
    display: block;
}

.default-menu-drawer__content .line-container--2.line-container--medium,
.default-menu-drawer__content .line-container--2.line-container--wide,
.default-menu-drawer__content .line-container--3.line-container--medium,
.empty-space--2.empty-space--medium,
.empty-space--2.empty-space--wide,
.empty-space--3.empty-space--medium {
    grid-column: span 2;
}

.default-menu-drawer__content .line-container--3.line-container--wide,
.empty-space--3.empty-space--wide {
    grid-column: span 3;
}

.default-menu-drawer__content .line-container--1.line-container--short .line,
.line-container--1.line-container--short .line {
    width: calc(100% / 3);
}

.default-menu-drawer__content .line-container--1.line-container--medium .line,
.line-container--1.line-container--medium .line {
    width: calc(100% / 3 * 2);
}

@media screen and (max-width: 1024px) {
    .default-menu-drawer {
        padding: 56px 0 48px;
    }

    .default-menu-drawer__content--spacious {
        padding: 96px var(--left-and-right-paddings);
        gap: 64px 83px;
        --grid-gap: 83px;
    }
    
    .default-menu-drawer__content--compact {
        padding: 32px var(--left-and-right-paddings) 0;
        gap: 32px 83px;
        --grid-gap: 83px;
    }
}

@media screen and (max-width: 920px) {
    .default-menu-drawer__content--spacious {
        padding: 96px 24px;
        gap: 128px 120px;
        --grid-gap: 120px;
    }
    
    .default-menu-drawer__content--compact {
        padding: 48px 24px;
        gap: 48px 120px;
        --grid-gap: 120px;
    }
}

@media screen and (max-width: 768px) {
    .default-menu-drawer__content {
        display: flex;
        flex-direction: column;
    }

    .default-menu-drawer__content .empty-space {
        display: none;
    }

    .default-menu-drawer {
        padding: 48px 0;
    }

    .default-menu-drawer__content--spacious {
        padding: 48px 24px;
        gap: 48px;
        --grid-gap: 48px;
    }
    
    .default-menu-drawer__content--compact {
        padding: 32px 24px 0;
        gap: 32px;
        --grid-gap: 32px;
    }
    .default-menu-drawer__content .line-container--1.line-container--short .line,
    .default-menu-drawer__content .line-container--1.line-container--medium .line {
        width: 100%;
    }
    .default-menu-drawer .menu-drawer__close {
        position: fixed;
        top: 16px;
        inset-inline-end: 16px;
