    position: relative;
    width: 100%;
}
.hover-reveal {
    display: flex;
	position: fixed;
	width: var(--image-width);
	height: fit-content;
	top: 100%;
	left: 0;
	pointer-events: none;
	opacity: 0;
    z-index: 7;
    transition: top calc(var(--animation-duration) / 4) linear, left calc(var(--animation-duration) / 4) linear;
}

@media (hover: hover) {
